    # Build adjacency list
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # If s == t, return 0
    if s == t:
        return 0

    # Bellman-Ford algorithm to find shortest path from s to t
    # Since the graph may have cycles, but weights are non-negative,
    # we use Bellman-Ford which handles this
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax all edges up to n-1 times
    for i in range(n - 1):
        updated = False
        for u in graph:
            for v, w in graph[u]:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
