    from collections import defaultdict, deque

    if s == t:
        return 0

    # Build the graph
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # BFS with Dijkstra's algorithm for shortest path
    dist = [-1] * n
    dist[s] = 0
    queue = deque([s])

    while queue:
        current = queue.popleft()
        for neighbor, weight in graph[current]:
            if dist[neighbor] == -1:
                dist[neighbor] = dist[current] + weight
