from collections import deque

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford to detect negative cycles and find shortest path
    # We'll use a modified Bellman-Ford to handle possible negative cycles
    # and find the shortest path from s to t

    # Initialize distance array
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n-1):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    # Check for negative weight cycles that are reachable from s
    for u in range(n):
        if dist[u] == float('inf'):
            continue
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                # If we can still relax, there's a negative cycle
                # If t is reachable from this cycle, then t is reachable from s
                # So we need to check if t is reachable from u (via BFS)
                # We use BFS to check reachability from u to t
                visited = set()
                queue = deque([u])
                visited.add(u)
                while queue:
                    node = queue.popleft()
                    if node == t:
                        # t is reachable from u, which is part of a negative cycle
                        # So t is reachable from s
                        return -1
                    for neighbor, _ in graph[node]:
                        if neighbor not in visited:
                            visited.add(neighbor)
                            queue.append(neighbor)

    # If no negative cycle found and t is reachable
    if dist[t] != float('inf'):
        return dist[t]
    else:
        return -1
